#include "http_server.h"

#include <string.h>
#include <stdlib.h>
#include "freertos/FreeRTOS.h"
#include "freertos/semphr.h"
#include "esp_log.h"
#include "esp_http_server.h"

static const char *TAG = "http_server";

/* -----------------------------------------------------------------------
 * Embedded web files (generated by CMake EMBED_TXTFILES)
 * ----------------------------------------------------------------------- */
extern const uint8_t index_html_start[]    asm("_binary_web_index_html_start");
extern const uint8_t index_html_end[]      asm("_binary_web_index_html_end");
extern const uint8_t tetris_html_start[]   asm("_binary_web_tetris_html_start");
extern const uint8_t tetris_html_end[]     asm("_binary_web_tetris_html_end");
extern const uint8_t game2048_html_start[] asm("_binary_web_game2048_html_start");
extern const uint8_t game2048_html_end[]   asm("_binary_web_game2048_html_end");

/* -----------------------------------------------------------------------
 * WebSocket client tracking
 * ----------------------------------------------------------------------- */
#define MAX_WS_CLIENTS 8

static httpd_handle_t s_server   = NULL;
static int            s_clients[MAX_WS_CLIENTS];
static SemaphoreHandle_t s_mutex = NULL;

static void clients_init(void)
{
    for (int i = 0; i < MAX_WS_CLIENTS; i++) {
        s_clients[i] = -1;
    }
}

static void client_add(int fd)
{
    xSemaphoreTake(s_mutex, portMAX_DELAY);
    for (int i = 0; i < MAX_WS_CLIENTS; i++) {
        if (s_clients[i] == -1) {
            s_clients[i] = fd;
            ESP_LOGI(TAG, "WS client added fd=%d (slot %d)", fd, i);
            break;
        }
    }
    xSemaphoreGive(s_mutex);
}

static void client_remove(int fd)
{
    xSemaphoreTake(s_mutex, portMAX_DELAY);
    for (int i = 0; i < MAX_WS_CLIENTS; i++) {
        if (s_clients[i] == fd) {
            s_clients[i] = -1;
            ESP_LOGI(TAG, "WS client removed fd=%d (slot %d)", fd, i);
            break;
        }
    }
    xSemaphoreGive(s_mutex);
}

/* -----------------------------------------------------------------------
 * HTTP handlers
 * ----------------------------------------------------------------------- */
static esp_err_t handler_index(httpd_req_t *req)
{
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    httpd_resp_send(req,
                    (const char *)index_html_start,
                    (ssize_t)(index_html_end - index_html_start));
    return ESP_OK;
}

static esp_err_t handler_tetris(httpd_req_t *req)
{
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    httpd_resp_send(req,
                    (const char *)tetris_html_start,
                    (ssize_t)(tetris_html_end - tetris_html_start));
    return ESP_OK;
}

static esp_err_t handler_2048(httpd_req_t *req)
{
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    httpd_resp_send(req,
                    (const char *)game2048_html_start,
                    (ssize_t)(game2048_html_end - game2048_html_start));
    return ESP_OK;
}

/* -----------------------------------------------------------------------
 * WebSocket handler
 * ----------------------------------------------------------------------- */
static esp_err_t handler_ws(httpd_req_t *req)
{
    if (req->method == HTTP_GET) {
        /* New WebSocket handshake */
        int fd = httpd_req_to_sockfd(req);
        ESP_LOGI(TAG, "WS handshake fd=%d", fd);
        client_add(fd);
        return ESP_OK;
    }

    /* Receive a frame */
    httpd_ws_frame_t pkt;
    memset(&pkt, 0, sizeof(pkt));

    /* First call: get frame length */
    esp_err_t ret = httpd_ws_recv_frame(req, &pkt, 0);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "recv_frame (len) failed: %d", ret);
        return ret;
    }

    if (pkt.len == 0) {
        return ESP_OK;
    }

    uint8_t *buf = calloc(1, pkt.len + 1);
    if (!buf) {
        return ESP_ERR_NO_MEM;
    }
    pkt.payload = buf;

    /* Second call: get frame payload */
    ret = httpd_ws_recv_frame(req, &pkt, pkt.len);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "recv_frame (data) failed: %d", ret);
        free(buf);
        return ret;
    }

    if (pkt.type == HTTPD_WS_TYPE_CLOSE) {
        int fd = httpd_req_to_sockfd(req);
        client_remove(fd);
    } else {
        ESP_LOGD(TAG, "WS rx: %s", (char *)buf);
    }

    free(buf);
    return ESP_OK;
}

/* -----------------------------------------------------------------------
 * Public API
 * ----------------------------------------------------------------------- */
void ws_broadcast(const char *msg)
{
    if (!s_server || !msg) return;

    httpd_ws_frame_t pkt = {
        .final      = true,
        .fragmented = false,
        .type       = HTTPD_WS_TYPE_TEXT,
        .payload    = (uint8_t *)msg,
        .len        = strlen(msg),
    };

    xSemaphoreTake(s_mutex, portMAX_DELAY);
    for (int i = 0; i < MAX_WS_CLIENTS; i++) {
        if (s_clients[i] == -1) continue;

        esp_err_t ret = httpd_ws_send_frame_async(s_server, s_clients[i], &pkt);
        if (ret != ESP_OK) {
            ESP_LOGW(TAG, "send failed fd=%d err=%d – removing", s_clients[i], ret);
            s_clients[i] = -1;
        }
    }
    xSemaphoreGive(s_mutex);
}

void http_server_start(void)
{
    s_mutex = xSemaphoreCreateMutex();
    clients_init();

    httpd_config_t cfg = HTTPD_DEFAULT_CONFIG();
    cfg.server_port      = 80;
    cfg.max_uri_handlers = 8;

    if (httpd_start(&s_server, &cfg) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to start HTTP server");
        return;
    }

    /* Static page handlers */
    static const httpd_uri_t uri_index = {
        .uri     = "/",
        .method  = HTTP_GET,
        .handler = handler_index,
    };
    static const httpd_uri_t uri_tetris = {
        .uri     = "/tetris",
        .method  = HTTP_GET,
        .handler = handler_tetris,
    };
    static const httpd_uri_t uri_2048 = {
        .uri     = "/2048",
        .method  = HTTP_GET,
        .handler = handler_2048,
    };

    /* WebSocket handler */
    static const httpd_uri_t uri_ws = {
        .uri          = "/ws",
        .method       = HTTP_GET,
        .handler      = handler_ws,
        .is_websocket = true,
    };

    httpd_register_uri_handler(s_server, &uri_index);
    httpd_register_uri_handler(s_server, &uri_tetris);
    httpd_register_uri_handler(s_server, &uri_2048);
    httpd_register_uri_handler(s_server, &uri_ws);

    ESP_LOGI(TAG, "HTTP server started on port 80");
}